def interval_rule(g,wall,fv):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(h):
        nines=[c for c in range(w) if g[r][c]==wall]
        for i in range(len(nines)-1):
            for c in range(nines[i]+1,nines[i+1]):
                if g[r][c]!=wall: out[r][c]=fv
    for c in range(w):
        nines=[r for r in range(h) if g[r][c]==wall]
        for i in range(len(nines)-1):
            for r in range(nines[i]+1,nines[i+1]):
                if g[r][c]!=wall: out[r][c]=fv
    return out
